-- UST Campus Store case study (CSELEC1C). Practice data, not real sales.
\set ON_ERROR_STOP on
SET client_min_messages = warning;
-- Session 2, step 1 (CDC with a watermark).
-- The store kept selling. This adds the sales of May 2 to 7, 2026 to src.sales
-- and corrects a few older rows. Every new or changed row has a newer updated_at.
-- Run it once. Note your watermark BEFORE you run it.

BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM src.sales WHERE updated_at >= '2026-05-02') THEN
  RAISE EXCEPTION 'This file was already applied. Reload 01_campus_store_source.sql to start over.'; END IF; END $$;

COPY src.sales (receipt_no, line_no, sold_at, branch_code, product_code, customer_id, txn_type, quantity, unit_price, discount, line_total, payment_method, updated_at) FROM stdin WITH (FORMAT csv);
